public static void addToClassPath(Vector<URL> cpV, String dir) {
    // Ensure the directory exists to avoid exceptions
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("The provided directory does not exist or is not a directory.");
    }

    // Add all JAR files in the directory to the classpath
    File[] files = directory.listFiles((file) -> file.toString().endsWith(".jar") || file.toString().endsWith(".zip"));
    if (files == null) {
        throw new RuntimeException("Error listing files in the directory.");
    }

    for (File file : files) {
        try {
            cpV.add(file.toURI().toURL());
        } catch (MalformedURLException e) {
            throw new RuntimeException("Error adding JAR file to the classpath.", e);
        }
    }
}
