public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (!dirFile.exists()) {
        throw new IllegalArgumentException("Directory does not exist: " + dir);
    }
    if (!dirFile.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a directory: " + dir);
    }
    File[] files = dirFile.listFiles(file -> file.isFile() && file.getName().endsWith(".jar"));
    if (files == null) {
        throw new IllegalArgumentException("Could not list files in directory: " + dir);
    }
    for (File file : files) {
        if (file != null) {
            try {
                URL url = file.toURI().toURL();
                cpV.add(url);
            } catch (MalformedURLException e) {
                throw new IllegalArgumentException("Failed to add file to classpath: " + file.getAbsolutePath(), e);
            }
        }
    }
}
