public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = buffer.size(1) + schema.size(message);
    if (size > buffer.capacity()) {
        buffer.resize(size);
    }

    int position = buffer.writeInt(schema.length(message));
    schema.write(message, position);
    out.write(buffer.array(), position);
    return size;
}
