public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType && targetType instanceof Class) {
        Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
        try {
            Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
            for (int i = 0; i < typeArguments.length; i++) {
                Type parameterType = typeArguments[i];
                if (parameterType instanceof Class) {
                    resolvedArguments[i] = (Class<?>) parameterType;
                } else if (parameterType instanceof WildcardType) {
                    WildcardType wildcard = (WildcardType) parameterType;
                    if (wildcard.getUpperBounds().length == 1) {
                        resolvedArguments[i] = Class.forName(wildcard.getUpperBounds()[0].getTypeName());
                    } else if (wildcard.getLowerBounds().length == 1) {
                        resolvedArguments[i] = Class.forName(wildcard.getLowerBounds()[0].getTypeName());
                    }
                } else if (parameterType instanceof TypeVariable) {
                    TypeVariable<?> typeVariable = (TypeVariable<?>) parameterType;
                    ParameterizedType parameterizedType = (ParameterizedType) targetType;
                    for (Type bound : parameterizedType.getActualTypeArguments()) {
                        if (bound instanceof Class && ((Class<?>) bound).getName().equals(typeVariable.getName())) {
                            resolvedArguments[i] = bound;
                            break;
                        }
                    }
                }
            }
            return resolvedArguments;
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to resolve class for argument " + parameterType, e);
        }
    }
    return null;
}
