public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        if (actualTypeArguments == null || actualTypeArguments.length == 0) {
            return null;
        }
        Class<?>[] resolvedTypes = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            resolvedTypes[i] = resolveType(actualTypeArguments[i], targetType);
        }
        return resolvedTypes;
    }

    private static Class<?> resolveType(Type type, Class<?> targetType) {
        if (type instanceof Class<?>) {
            return (Class<?>) type;
        } else if (type instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) type;
            final Class<?>[] upperBoundTypes = wildcardType.getUpperBounds();
            if (upperBoundTypes.length == 0) {
                return null;
            }
            return resolveType(upperBoundTypes[0], targetType);
        } else if (type instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) type;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            return resolveType(actualTypeArguments[0], targetType);
        } else if (type instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) type;
            Type[] bounds = typeVariable.getBounds();
            if (bounds.length == 0) {
                return null;
            }
            return resolveType(bounds[0], targetType);
        } else {
            return null;
        }
    }
