public boolean equals(final byte[] data, int offset, final int len) {
    // Check if data, offset, and len are valid inputs
    if (data == null || len <= 0 || data.length - offset < len) {
        throw new IllegalArgumentException("Invalid data, offset, or length");
    }

    // Compare the data arrays element by element
    for (int i = offset; i < offset + len; i++) {
        if (data[i] != this.data[i]) {
            return false;
        }
    }

    // If all elements match, return true
    return true;
}
