private static final long FETCH_DATA_DURATION = 10; // ultra short duration in milliseconds

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start + FETCH_DATA_DURATION >= end || start >= end - FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long startRange = start;
        long endRange = start + FETCH_DATA_DURATION;
        while (endRange <= end) {
            timeRanges.add(new TimeRange(startRange, endRange));
            startRange = endRange;
            endRange += FETCH_DATA_DURATION;
        }
        if (startRange < end) {
            timeRanges.add(new TimeRange(startRange, end));
        }
    }
    return timeRanges;
}
