public static int computeUTF8Size(CharSequence str, final int index, final int len) {
    if (str == null || index >= str.length() || len <= 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    if (index + len > str.length()) {
        throw new IllegalArgumentException("Substring exceeds the length of the string");
    }

    int size = 0;
    for (int j = 0; j < len; j++) {
        char ch = str.charAt(index + j);
        if (ch >= 0x80 && ch < 0xE0) {
            size += 1;
        } else if (ch >= 0xC0 && ch < 0xF0) {
            int left = ch & 0x1F;
            ch = str.charAt(index + j + 1);
            if (ch >= 0x80 && ch < 0xBF) {
                size += 2;
            } else if (ch >= 0x80 && ch < 0xF0) {
                size += 3;
            }
        } else if (ch >= 0xE0 && ch < 0xF0) {
            int left = ch & 0x0F;
            ch = str.charAt(index + j + 1);
            if (ch >= 0x80 && ch < 0xBF) {
                size += 3;
            } else if (ch >= 0x80 && ch < 0xF0) {
                size += 4;
            }
        } else if (ch >= 0xF0 && ch < 0xF8) {
            int left = ch & 0x07;
            ch = str.charAt(index + j + 1);
            if (ch >= 0x80 && ch < 0xBF) {
                size += 4;
            } else if (ch >= 0x80 && ch < 0xF0) {
                size += 5;
            }
        } else if (ch >= 0xF8 && ch < 0xFC) {
            int left = ch & 0x03;
            ch = str.charAt(index + j + 1);
            if (ch >= 0x80 && ch < 0xBF) {
                size += 5;
            } else if (ch >= 0x80 && ch < 0xF0) {
                size += 6;
            }
        } else if (ch >= 0xFC && ch < 0xFE) {
            int left = ch & 0x01;
            ch = str.charAt(index + j + 1);
            if (ch >= 0x80 && ch < 0xBF) {
                size += 6;
            } else if (ch >= 0x80 && ch < 0xF0) {
                size += 7;
            }
        } else if (ch >= 0xFD) {
            throw new IllegalArgumentException("Invalid UTF-8 character");
        }
    }
    return size;
}
