        }
        localByteArrayValue = new byte[byteLength];
        for (int i = 0; i < byteLength; i++) {
            localByteArrayValue[i] = 0;
        }
    }
    byte[] localByteArrayValueCopy = new byte[byteArrayValue.length - byteOffset];
    System.arraycopy(localByteArrayValue, byteOffset, localByteArrayValueCopy, 0, byteLength);
    this.array = java.util.Arrays.copyOf(this.array, this.array.length + byteLength);
    System.arraycopy(localByteArrayValueCopy, 0, this.array, this.size, byteLength);
    this.size += byteLength;
    return this;
