public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    // Iterate over each character and UTF-8 encode it into the LinkedBuffer
    for (int i = 0; i < str.length(); i++) {
        int c = str.charAt(i);

        if (c < 0x80) {
            lb.put((byte) c);
        } else if (c < 0x800) {
            lb.put((byte) (0xc0 | (c >> 6));
            lb.put((byte) (0x80 | (c & 0x3f)));
        } else if (c >= 0x800 && c < 0xD800) {
            if (i + 1 < str.length()) {
                int d = str.charAt(i + 1);
                if (d >= 0xDC00 && d <= 0xDFFF) {
                    // Process supplementary code point
                    c = 0x10000 + ((c - 0xD800) << 10) | (d - 0xDC00);
                    lb.put((byte) (0xe0 | (c >> 12)));
                    lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                    lb.put((byte) (0x80 | (c & 0x3F)));
                    i++; // Skip the next character
                } else {
                    // Handle invalid supplementary code point
                    throw new IllegalArgumentException("Supplementary code point out of range");
                }
            } else {
                // Handle unterminated supplementary code point
                throw new IllegalArgumentException("Supplementary code point incomplete, incomplete character");
            }
        } else if (c >= 0xD800 && c <= 0xFFFF) {
            if (i + 1 < str.length()) {
                int d = str.charAt(i + 1);
                if (d >= 0xDC00 && d <= 0xDFFF) {
                    // Process supplementary code point
                    c = 0x10000 + ((c - 0xD800) << 10) | (d - 0xDC00);
                    lb.put((byte) (0xf0 | (c >> 18)));
                    lb.put((byte) (0x80 | ((c >> 12) & 0x3F)));
                    lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                    lb.put((byte) (0x80 | (c & 0x3F)));
                    i++; // Skip the next character
                } else {
                    // Handle invalid supplementary code point
                    throw new IllegalArgumentException("Supplementary code point out of range");
                }
            } else {
                // Handle unterminated supplementary code point
                throw new IllegalArgumentException("Supplementary code point incomplete, incomplete character");
            }
        } else {
            // Handle non-BMP characters (UTF-32)
            lb.put((byte) (0xf0 | (c >> 18)));
            lb.put((byte) (0xc0 | ((c >> 12) & 0x3F)));
            lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (c & 0x3F)));
        }
    }

    return lb;
}
