            lb.putInt(0x80 | (codePoint >>> 18));
            lb.putInt(0x80 | (codePoint >>> 12));
            lb.putInt(0x80 | (codePoint >>> 6));
            lb.putInt(0x80 | (codePoint & 0x3F));
