            }
            writeUTF8Continues(c, 4, lb);
            session踉motion(1);
        } else {
            if (c < 0xF8) {
                if (lb.getFreeSpace() < 5) {
                    throw new IllegalArgumentException("Not enough space to encode character.");
                }
                writeUTF8Continues(c, 5, lb);
                session踉motion(1);
            } else {
