private static void writeUTF8Continues(int c, int n, LinkedBuffer lb) {
    byte[] bytes = new byte[n];
    bytes[0] = (byte) ((c & 0x1F) | 0xC0);
    for (int i = 1; i < n; i++) {
        bytes[i] = (byte) (0x80 | (c & 0x3F));
        c >>= 6;
    }
    lb.write(bytes);
