private static List<PathSegmentImpl> decodeSegments(String path, boolean leadingSlashIgnored, List<PathSegmentImpl> pathSegments) {
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    if (leadingSlashIgnored) {
        path = path.substring(1);
    }

    int startIndex = 0;
    while (startIndex < path.length()) {
        int endIndex = path.indexOf('/', startIndex);
        if (endIndex == -1) {
            endIndexOf = path.length();
        }

        String segment = path.substring(startIndex, endIndex);

        if (!segment.isEmpty()) {
            pathSegments.add(PathSegmentImpl.newInstance(segment));
        }

        startIndex = endIndexOf + 1;
        leadingSlashIgnored = false;
    }

    return pathSegments;
}
