public static String peek() {
    StackTraceElement[] stackTraceElements = Thread.currentThread().getStackTrace();
    if (stackTraceElements.length > 1) {
        // Remove the peeking method
        String[] newStackTrace = java.util.Arrays.copyOf(stackTraceElements, stackTraceElements.length - 1);
        StackTraceElement[] trimmedStackTrace = new java.util.Arrays.copyOfRange(newStackTrace, 1, newStackTrace.length);

        StackTraceElement peekingElement = trimmedStackTrace[trimmedStackTrace.length - 1];
        return peekingElement.getFileName() + ":" + peekingElement.getLineNumber() + ":" + peekingElement.getMethodName();
    } else {
        return "";
    }
}
