    // Check if the input is a valid positive integer greater than 0
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("The input value must be a valid positive integer greater than 0");
    }

    // Special case for 0 and 1 directly
    if (desiredCapacity == 0) {
        return 2;
    }
    if (desiredCapacity == 1) {
        return 3;
    }

    final int base = (desiredCapacity >= 1000) ? 1 : 2;
    // Use a set to keep track of already found primes
    Set<Integer> primes = new HashSet<>();

    int candidate = base;
    int prime;

    while (true) {
        // Check if the candidate is divisible by any known prime
        for (prime : primes) {
            if (candidate % prime == 0) {
                break;
            }
        }
        // If no divisors found, it's a prime number
        if (prime == Integer.MAX_VALUE) {
            prime = candidate;
            prime--;
        }

        if (prime >= desiredCapacity) {
            return prime;
        }

        // Add the prime number to the set
        primes.add(prime + 2); // Skip any even numbers greater than 2

        // Increment the candidate to continue searching
        candidate += 2;
    }
}
