private Map<String, Object> buildContent(JsonObject jsonObject) {
    if (jsonObject == null) {
        throw new IllegalArgumentException("Input jsonObject cannot be null");
    }

    Map<String, Object> contentMap = new HashMap<>();
    for (String key : jsonObject.keySet()) {
        Object value = jsonObject.get(key);
        if (value instanceof JsonNumber) {
            contentMap.put(key, ((JsonNumber) value).longValue());
        } else if (value instanceof JsonArray) {
            contentMap.put(key, ((JsonArray) value).stream()
                                                    .map(Object::toString)
                                                    .collect(Collectors.toList()));
        } else {
            contentMap.put(key, value);
        }
    }

    if (jsonObject.has("ats")) {
        Object atsValue = jsonObject.get("ats");
        if (atsValue instanceof JsonObject) {
            contentMap.put("ats", buildContent((JsonObject) atsValue));
        }
    }

    return contentMap;
}
