public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    StringBuilder builder = new StringBuilder();

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (c == '\\' && i + 1 < str.length()) {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'b') {
                builder.append('\b');
            } else if (nextChar == 't') {
                builder.append('\t');
            } else if (nextChar == 'n') {
                builder.append('\n');
            } else if (nextChar == 'r') {
                builder.append('\r');
            } else if (nextChar == '\\' && i + 2 < str.length()) {
                char nextNextChar = str.charAt(i + 2);
                if (nextNextChar == 'n') {
                    builder.append('\u0085');
                } else if (nextNextChar == 'f') {
                    builder.append('\u2028');
                } else if (nextNextChar == 'l') {
                    builder.append('\u2029');
                } else if (nextNextChar == '=' && i + 3 < str.length()) {
                    char nextNextNextChar = str.charAt(i + 3);
                    if (nextNextNextChar == '>' && c == '>' && nextNextNextChar == '=') {
                        builder.append("\\u20AC");
                    } else {
                        throw new IllegalArgumentException("Invalid escape sequence: " + str.substring(i, i + 4));
                    }
                }
            } else if (nextChar == 'x') {
                if (i + 4 < str.length() && str.charAt(i + 2) == '0' && str.charAt(i + 3) == 'x') {
                    throw new IllegalArgumentException("Invalid escape sequence: " + str.substring(i, i + 5));
                }
                builder.append((char) Integer.parseInt(str.substring(i + 2, i + 4), 16));
                i += 3;
            } else if (nextChar == 'u') {
                if (i + 5 < str.length() && str.charAt(i + 2) == '0' && str.charAt(i + 3) == 'x') {
                    throw new IllegalArgumentException("Invalid escape sequence: " + str.substring(i, i + 6));
                }
                builder.append((char) Integer.parseInt(str.substring(i + 2, i + 5), 16));
                i += 4;
            } else {
                builder.append(c);
            }
        } else {
            builder.append(c);
        }
    }

    result.append(builder.toString());

    if (result.length() > 0 && result.charAt(result.length() - 1) == '\\') {
        throw new IllegalArgumentException("String ends with backslash");
    }

    return result.toString();
}
