public static String unescapeJava(String str) throws Exception {
    if (str == null)
        return null;
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case '\\':
                        sb.append('\\');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'u':
                        if (i + 5 < len) {
                            // 4 hexadecimal digits representing Unicode character
                            int codePoint = Integer.parseInt(str.substring(i + 2, i + 6), 16);
                            if (codePoint > 0) {
                                sb.append(Character.toChars(codePoint));
                                i += 5;
                            } else {
                                throw new Exception("Invalid Unicode escape sequence");
                            }
                        } else {
                            throw new Exception("Invalid Unicode escape sequence");
                        }
                        break;
                    default:
                        throw new Exception("Unexpected escape sequence");
                }
                i++; // Skip the character after '\'
            } else {
                throw new Exception("Unexpected end of string in escape sequence");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
