public static String unescapeJava(String str) throws Exception {
    StringBuilder result = new StringBuilder();
    StringBuilder escapeBuffer = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case '\'':
                        escapeBuffer.append(c);
                        i++; // Step over the next char
                        break;
                    case '"':
                        result.append(c);
                        i++; // Step over the next char
                        break;
                    case '\\':
                        result.append(c); // Backslash as is
                        break;
                    case 'n':
                        result.append('\n'); // Newline
                        break;
                    case 't':
                        result.append('\t'); // Tab
                        break;
                    case 'r':
                        result.append('\r'); // Carriage return
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid escape sequence \\u" + Integer.toHexString((nextChar & 0xFF) | 0x80));
                }
            } else {
                escapeBuffer.append(c); // Last char, no escape sequence
            }
        } else if (escapeBuffer.length() > 0) {
            int '\\u' + Integer.toHexString((escapeBuffer.charAt(0) & 0xFF) | 0x80);
            result.append(escapeBuffer);
            escapeBuffer.setLength(0);
        } else {
            result.append(c);
        }
    }
    if (escapeBuffer.length() > 0) {
        int '\\u' + Integer.toHexString((escapeBuffer.charAt(0) & 0xFF) | 0x80);
        result.append(escapeBuffer);
    }
    return result.toString();
}
