private static String javaCharset(String charset) throws IllegalArgumentException {
	if (charset == null) {
		throw new IllegalArgumentException("charset is null");
	}
	if (charset.length() < 2) {
		throw new IllegalArgumentException("charset is too short");
	}
	if (charset.charAt(0) != '!') {
		throw new IllegalArgumentException("charset does not start with !");
	}
	String javaName = charset.substring(1);
	for (char c : javaName.toCharArray()) {
		if (!Character.isLetterOrDigit(c) && c != '-') {
			throw new IllegalArgumentException("charset contains invalid character: " + c);
		}
	}
	return javaName;
}
