private String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPoolTable.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    final int stringStart = constantPoolTable[constantPoolEntryIndex] >>> 8 & 0xFF;
    final int stringLength = constantPoolTable[constantPoolEntryIndex] & 0xFF;
    charBuffer[0] = (char) (stringStart & 0xFF);
    int index = 1;
    int bytesRead = 0;
    while (bytesRead < stringLength) {
        final int codePoint = readUnsignedIntFromBuffer(classFileBuffer, 8 + bytesRead);
        if (codePoint == 0xFFFF) {
            final int continuationOffset = readSignedShortFromBuffer(classFileBuffer, 10 + bytesRead);
            index++; // Skip continuation character
            bytesRead += 2;
            while (codePoint < 0xFFFF) {
                index++;
                bytesRead += 2;
                codePoint = readUnsignedIntFromBuffer(classFileBuffer, 8 + bytesRead);
            }
            final char continuationChar = (char) (codePoint & 0xFFFF);
            charBuffer[index++] = continuationChar;
            bytesRead++;
        } else {
            charBuffer[index] = (char) codePoint;
            bytesRead++;
        }
    }
    return new String(charBuffer, 0, index);
}
