    if (entryType ==TagConstants.CONSTANT_Utf8) {
        int length = classFileBuffer.get(classFileBuffer.currentIndex() + 4);
        classFileBuffer.currentIndex() = classFileBuffer.currentIndex() + 5;
        int offset = classFileBuffer.get(classFileBuffer.currentIndex());

        for (int i = 0; i < length; i++) {
            charBuffer[offset + i] = (char) classFileBuffer.get(classFileBuffer.currentIndex());
            classFileBuffer.currentIndex()++;
        }

        return new String(charBuffer);
    } else {
        throw new IllegalArgumentException("Invalid constant pool entry type for utf-8 constant");
