public static byte convertHexDigit(byte b) {
    // Convert ASCII digit to binary
    byte temp = (byte) (b - 48); // 0-9 digits are subtracted from 0 to get their binary value without the '0.'

    // If the character is A-F,
    if (b >= 65) // ASCII codes for A-F are between 65 and 90.
        temp -= 32; // Subtract 32 (2^5) times to get the actual binary value of A-F

    // Shift the binary value to the left and get the first bit
    return (byte) ((temp >> 5) & 1); // Mask with 0b0001 to get the least significant bit.
}
