int addConstantNameAndType(final String name, final String descriptor) {
    // Acquire a lock on the constant pool to ensure thread safety
    synchronized (super.getConstantPool()) {
        // Search the constant pool for an existing item with the same name and descriptor
        int existingIndex = -1;
        for (int i = 0; i < super.getConstantPool().getCount(); i++) {
            if (super.getConstantPool().getConstant(i).getTagName() == ConstantTag.CONSTANT_NameAndType && 
                super.getConstantPool().getConstant(i).getConstantValue() == name &&
                super.getConstantPool().getConstant(i).hasStringValue(descriptor)) {
                existingIndex = i;
                break;
            }
        }

        // If the constant with the similar name and descriptor is found, return its index
        if (existingIndex != -1) {
            return existingIndex;
        }

        // Otherwise, create a new Constant_NameAndType_info and add it to the constant pool
        int newId = super.getConstantPool().addConstnameAndType(name, descriptor);
        return newId;
    }
}
