private String unescapeId(String input) {
    StringBuilder builder = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i == len - 1) {
                throw new IllegalArgumentException("Invalid escape sequence");
            }
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    builder.append('\n');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 'b':
                    builder.append('\b');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case '"':
                    builder.append('"');
                    break;
                case '\'':
                    builder.append('\'');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence escape: " + next);
            }
            i++;
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}
