        throw new IllegalArgumentException("Input cannot be null");
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i += 1;
            if (i == input.length()) {
                throw new IllegalArgumentException("Escape sequence followed by end of string");
            }
            char escapeChar = input.charAt(i);
            if (escapeChar == 't') {
                result.append('\t');
            } else if (escapeChar == 'n') {
                result.append('\n');
            } else if (escapeChar == 'r') {
                result.append('\r');
            } else {
                throw new IllegalArgumentException("Unsupported escape character: " + escapeChar);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}
