private String unescapeId(String input) throws RuntimeException {
    StringBuilder sb = new StringBuilder();
    boolean escape = false;
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (escape) {
            if (c == '\\') sb.append(c);
            else if (c == '\"') sb.append('"');
            else if (c == '\\' && isOctalEscape(c)) sb.append(byteToCharNibble(c));
            else if (c == '\\' && isHexEscape(c)) sb.append(hexToCharNibble(c));
            else if (c == '\\' && i + 1 < input.length()) sb.append(input.charAt(i + 1));
            escape = false;
        } else if (c == '\\') {
            escape = true;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private byte byteToCharNibble(char in) {
    return (byte) ((in & 0x7) + '0');
}

private char hexToCharNibble(char in) {
    if (in >= '0' && in <= '9') return in;
    if (in >= 'A' && in <= 'F') return in - 'A' + 0x10;
    if (in >= 'a' && in <= 'f') return in - 'a' + 0x10;
    return 0;
}

private boolean isOctalEscape(char in) {
    return in >= '0' && in <= '7';
}

private boolean isHexEscape(char in) {
    return in >= '0' && in <= 'F' || in >= 'a' && in <= 'f';
}
