private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if buckets are available
    if (bucketsByLabel == null || bucketsByLabel.size() == 0) {
        throw new IllegalArgumentException("Buckets must be non-null and not empty.");
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Create a new bucket with label 0
    List<Integer> newBucket = new ArrayList<>();
    Set<Integer> newBucketSet = new HashSet<>();
    for (int label : labels) {
        if (label != minLabel) {
            newBucket.add(label);
            newBucketSet.add(label);
            // Check if the new bucket is non-empty
            if (newBucket.size() > 0) {
                // Sort the new bucket
                Collections.sort(newBucket);
                // Add the new bucket to the bucketsByLabel map
                bucketsByLabel.computeIfAbsent(0, k -> new HashSet<>()).addAll(newBucketSet);
            }
        }
    }
}
