public static final <V> void reverse(V[] arr, int from, int to) {
    // Check if the from index is less than the to index, otherwise swap the indices
    if (from < to) {
        while (from < to) {
            // Swap the elements at the from and to indices
            V temp = arr[from];
            arr[from] = arr[to];
            arr[to] = temp;
            // Move the from index backward and the to index forward
            from++;
            to--;
        }
    } else {
        throw new IllegalArgumentException("from must be less than to");
    }
}
