private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    if (this.graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    int n = this.graph.vertices().size();
    List<Pair<List<Pair<Integer,Integer>>, E>> result = new ArrayList<>();

    for (E edge : this.graph.edges()) {
        Node<Integer> startVertex = this.graph.getNode(edge.source());
        Node<Integer> endVertex = this.graph.getNode(edge.target());
        List<Pair<Integer, Integer>> separatorList = new ArrayList<>();

        // Compute minimal separators in the neighborhood of the edge
        for (Node<Integer> neighbor : startVertex.neighbors()) {
            if (neighbor != endVertex && neighbor.getId() != endVertex.getId()) {
                separatorList.addAll(computeMinimalSeparators(neighbor, endVertex));
            }
        }

        for (Node<Integer> neighbor : endVertex.neighbors()) {
            if (neighbor != startVertex && neighbor.getId() != startVertex.getId()) {
                separatorList.addAll(computeMinimalSeparators(endVertex, startVertex));
            }
        }

        result.add(new Pair<>(separatorList, edge));
    }

    return result;
}

private List<Pair<Integer, Integer>> computeMinimalSeparators(Node<Integer> startVertex, Node<Integer> endVertex) {
    List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
    Set<Node<Integer>> visited = new HashSet<>();
    Stack<Node<Integer>> stack = new Stack<>();
   (stack).push(startVertex);

    while (!stack.isEmpty()) {
        Node<Integer> currentVertex = stack.pop();
        visited.add(currentVertex);

        for (Node<Integer> neighbor : currentVertex.neighbors()) {
            if (!visited.contains(neighbor) && neighbor.getId() != endVertex.getId()) {
                separatorList.add(Pair.with(currentVertex.getId(), neighbor.getId()));
                visited.add(neighbor);
                stack.push(neighbor);
            }
        }
    }

    return separatorList;
}
