public ByteVector putInt(final int intValue) {
    // Check if the integer value is negative
    if (intValue < 0) {
        throw new IllegalArgumentException("Value must be non-negative");
    }

    int unsignedValue = intValue & 0x7FFFFFFF; // Ensure the value remains within the 32-bit range
    int byteCount = (int) Math.ceil(Math.log(unsignedValue) / Math.log(256));

    if (byteCount > ByteVector.MAX_LENGTH) {
        throw new IllegalArgumentException("Value is too large to fit in a byte vector");
    }

    ByteVector vector = new ByteVector(byteCount);
    int[] bytes = new int[byteCount];

    for (int i = 0; i < byteCount; i++) {
        bytes[i] = unsignedValue & 0xFF;
        unsignedValue >>= 8;
    }

    vector.append(bytes);

    return vector;
}
