public ByteVector putInt(final int intValue){
    int currentSize = vector.length;
    int newLength = Math.max(currentSize + 5, 2 * currentSize);
    byte[] newData = new byte[newLength];
    System.arraycopy(vector, 0, newData, 0, currentSize);
    int bytesWritten = putIntAt(newData, intValue, newData.length - 4, (currentSize - 4 & 3) + 1);
    // Shift the last bytes just written
    System.arraycopy(newData, newData.length - bytesWritten - 1, newData, newData.length - bytesWritten, bytesWritten);
    vector = newData;
    return this;
}
