    for (V node : vertices) {
        adj.put(node, node);
    }
    for (V node1 : vertices) {
        for (V node2 : vertices) {
            if (node1 == node2) {
                continue;
            }
            adj.computeIfAbsent(node1, v -> new HashSet<>()).add(node2);
            adj.computeIfAbsent(node2, v -> new HashSet<>()).add(node1);
        }
    }
    for (V node1 : vertices) {
        for (V node2 : vertices) {
            if (node1 == node2) {
                continue;
