        throw new IllegalArgumentException("Graph and vertices cannot be null");
    }
    if(vertices.isEmpty()) {
        return true;
    }
    if(graph.vertexSet().size() != vertices.size()) {
        throw new IllegalArgumentException("Vertex set size does not match the number of vertices in the set");
    }
    AtomicInteger count = new AtomicInteger(vertices.size());

    for (V v : vertices) {
        if(!graph.containsEdge(v,v)) {
            count.decrementAndGet();
            if(count.get() == 0) {
                break;
            }
        }
    }

    return count.get() == 0;
}
