public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return false;
    }

    Set<V> remainingVertices = new HashSet<>(vertices);
    for (V vertex : vertices) {
        remainingVertices.remove(vertex);
        for (V neighbor : graph.neighbors(vertex)) {
            remainingVertices.remove(neighbor);
            if (!remainingVertices.isEmpty()) {
                return false;
            }
            remainingVertices.clear();
        }
    }
    return true;
}
