    }

    Set<V> connectedVertices = new HashSet<>();
    for (V vertex : vertices) {
        connectedVertices.add(vertex);

        // Check if the vertex and all its neighbors are in the subset
        for (V neighbor : graph.neighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }

        // Check if there is more than one vertex that does not have the vertex in the subset
        if (graph.degree(vertex) >= vertices.size() - 1) {
            return false;
        }
    }

    return true;
