private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();

    // Handle potential invalid or too-large inputs
    if (keys == null || keys.size() == 0) {
        throw new IllegalArgumentException("Input list of keys is empty");
    }

    // Determine the maximum number of digits required to represent the key sizes
    int maxDigits = calculateMaxKeySizeDigits(keys);

    // Compute the upper bound for each key based on its size
    for (K key : keys) {
        upperBounds.add(computeKeyUpperBound(key, maxDigits));
    }

    return upperBounds;
}

private int calculateMaxKeySizeDigits(List<K> keys) {
    int maxSize = 0;
    for (K key : keys) {
        maxSize = Math.max(maxSize, key.toString().length());
    }
    return maxSize;
}

private int computeKeyUpperBound(K key, int maxDigits) {
    if (key.toString().length() == maxDigits) {
        return Integer.parseInt(key.toString());
    } else {
        // Pad the key with leading zeros to match the maximum number of digits
        String keyStr = key.toString();
        int padding = maxDigits - keyStr.length();
        return Integer.parseInt(keyStr + String.format("%0" + padding + "d", 0));
    }
}
